file_editor: {"command": "create", "file_text": "const WIDTH = 640;
const HEIGHT = 640;

const SECTORS = ["Information Technology", "Industry", "Energy", "Financial", "ETF"];
const SECTOR_COLORS = {
    "Information Technology": "#4e79a7",
    "Industry": "#f28e2b",
    "Energy": "#e15759",
    "Financial": "#59a14f",
    "ETF": "#9c755f"
};

function formatMarketCap(v) {
    if (v == null || isNaN(v)) return "N/A";
    const abs = Math.abs(v);
    if (abs >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (abs >= 1e9)  return (v / 1e9).toFixed(2) + "B";
    if (abs >= 1e6)  return (v / 1e6).toFixed(2) + "M";
    return v.toFixed(0);
}

d3.csv("data/stock-descriptions.csv").then(raw => {
    const data = raw.map(d => ({
        ticker: d.ticker,
        sector: d.sector,
        name: d["full name"],
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || "",
        website: d.website || ""
    }));

    data.sort((a, b) => {
        const sa = SECTORS.indexOf(a.sector), sb = SECTORS.indexOf(b.sector);
        if (sa !== sb) return sa - sb;
        return d3.ascending(a.ticker, b.ticker);
    });

    const nonEtfCaps = data.filter(d => d.sector !== "ETF" && d.marketCap).map(d => d.marketCap);
    const rScale = d3.scaleSqrt()
        .domain([d3.min(nonEtfCaps), d3.max(nonEtfCaps)])
        .range([14, 48]);
    const ETF_RADIUS = 20;

    data.forEach(d => {
        d.radius = d.sector === "ETF" ? ETF_RADIUS : rScale(d.marketCap);
    });

    const cx = WIDTH / 2, cy = HEIGHT / 2;
    const clusterRadius = Math.min(WIDTH, HEIGHT) * 0.28;
    const clusterCenters = {};
    SECTORS.forEach((s, i) => {
        const angle = (i / SECTORS.length) * 2 * Math.PI - Math.PI / 2;
        clusterCenters[s] = {
            x: cx + clusterRadius * Math.cos(angle),
            y: cy + clusterRadius * Math.sin(angle)
        };
    });

    data.forEach(d => {
        const c = clusterCenters[d.sector];
        d.x = c.x + (d.ticker.charCodeAt(0) % 10) - 5;
        d.y = c.y + (d.ticker.charCodeAt(d.ticker.length - 1) % 10) - 5;
    });

    renderBubbleChart(data, clusterCenters);
    renderLegend();
    renderTable(data);
    wireInteractions();
});

function renderBubbleChart(data, clusterCenters) {
    const svg = d3.select("#bubble-chart").append("svg")
        .attr("width", WIDTH)
        .attr("height", HEIGHT)
        .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`);

    const nodes = svg.append("g").selectAll("g.node")
        .data(data, d => d.ticker)
        .join("g")
        .attr("class", "node")
        .attr("data-ticker", d => d.ticker);

    nodes.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => SECTOR_COLORS[d.sector]);

    nodes.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .attr("font-size", d => Math.max(9, Math.min(14, d.radius * 0.5)));

    const sim = d3.forceSimulation(data)
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.18))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.18))
        .force("collide", d3.forceCollide(d => d.radius + 1.5).strength(1))
        .force("center", d3.forceCenter(WIDTH / 2, HEIGHT / 2).strength(0.02))
        .stop();

    for (let i = 0; i < 400; i++) sim.tick();

    nodes.attr("transform", d => `translate(${d.x},${d.y})`);
}

function renderLegend() {
    const legend = d3.select("#legend");
    SECTORS.forEach(s => {
        const item = legend.append("div").attr("class", "legend-item");
        item.append("span").attr("class", "legend-swatch")
            .style("background", SECTOR_COLORS[s]);
        item.append("span").text(s);
    });
}

function renderTable(data) {
    const tbody = d3.select("#stock-table tbody");
    tbody.selectAll("tr")
        .data(data, d => d.ticker)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .html(d => `
            <td>${d.ticker}</td>
            <td>${d.name}</td>
            <td>${d.sector}</td>
            <td>${d.sector === "ETF" ? "—" : formatMarketCap(d.marketCap)}</td>
        `);
}

function wireInteractions() {
    const tooltip = d3.select("#tooltip");

    d3.selectAll("#bubble-chart .node")
        .on("mouseover", function(event, d) {
            if (d.sector === "ETF") return;
            tooltip.classed("visible", true)
                .html(`
                    <div class="t-ticker">${d.ticker}</div>
                    <div class="t-row">${d.name}</div>
                    <div class="t-row">Sector: ${d.sector}</div>
                `);
        })
        .on("mousemove", function(event, d) {
            if (d.sector === "ETF") return;
            tooltip.style("left", (event.pageX + 12) + "px")
                   .style("top", (event.pageY + 12) + "px");
        })
        .on("mouseout", function() {
            tooltip.classed("visible", false);
        })
        .on("click", function(event, d) {
            selectTicker(d.ticker);
        });

    d3.selectAll("#stock-table tbody tr")
        .on("click", function(event, d) {
            selectTicker(d.ticker);
        });
}

function selectTicker(ticker) {
    d3.selectAll("#bubble-chart .bubble").classed("selected", false);
    d3.selectAll(`#bubble-chart .node[data-ticker="${ticker}"] .bubble`).classed("selected", true);

    d3.selectAll("#stock-table tbody tr").classed("selected", false);
    d3.selectAll(`#stock-table tbody tr[data-ticker="${ticker}"]`).classed("selected", true);

    const row = document.querySelector(`#stock-table tbody tr[data-ticker="${ticker}"]`);
    if (row) row.scrollIntoView({ block: "nearest", behavior: "smooth" });
}
